{
  "implementation": "def solve(case):
    nodes = {n['id']: n for n in case['nodes']}
    children_of = {n['id']: [] for n in case['nodes']}
    for n in case['nodes']:
        parent = n.get('parent')
        if parent is not None:
            children_of[parent].append(n['id'])
    required_symbols = set(case['required_symbols'])
    retained_ids = set(n['id'] for n in case['nodes'])
    symbol_counts = {}
    for n in case['nodes']:
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    sorted_nodes = sorted(case['nodes'], key=lambda n: (-n['depth'], n['id']))
    removed_ids = []
    for node in sorted_nodes:
        nid = node['id']
        if not node['removable']:
            continue
        sym = node['symbol']
        if sym in required_symbols and symbol_counts[sym] == 1:
            continue
        children = children_of.get(nid, [])
        if any(cid in retained_ids for cid in children):
            continue
        retained_ids.remove(nid)
        symbol_counts[sym] -= 1
        removed_ids.append(nid)
    retained_ids_sorted = sorted(retained_ids)
    return {"removed_node_ids": removed_ids, "retained_node_ids": retained_ids_sorted}"
}
